mapper.select:
SELECT MBRSH_SQ
  FROM CM_USER_ORGNZT_MBRSH
 WHERE CMPNY_CD = #{cmpnyCd}
   AND USER_ID = #{userId}
   AND IFNULL(USE_FL, 'Y') = 'Y'
 LIMIT 1

mapper.insert:
INSERT INTO CM_DASHBRD (
    DASHBRD_ID
  , CMPNY_CD
  , MBRSH_SQ
  , LAYOUT_JSON
  , CONFIG_JSON
  , USE_FL
  , CREATION_ID
  , UPDATE_ID
) VALUES (
    #{dashbrdId}
  , #{cmpnyCd}
  , #{mbrshSq}
  , 
        CAST(#{layoutJson} AS JSON)
        NULL

  , 
        CAST(#{configJson} AS JSON)
        NULL

  , IFNULL(#{useFl}, 'Y')
  , #{creationId}
  , #{updateId}
)

mapper.update:
UPDATE CM_DASHBRD SET LAYOUT_JSON = CAST(#{layoutJson} AS JSON) NULL
, CONFIG_JSON = CAST(#{configJson} AS JSON) NULL
, UPDATE_ID = #{updateId} , UPDATE_DT = CURRENT_TIMESTAMP WHERE DASHBRD_ID = #{dashbrdId} AND CMPNY_CD = #{cmpnyCd}
